for i,c in enumerate(concepts,1):c['sourceRoots']=phrases.get(i,c['sourceRoots'])
for s in base:
 s['intentEvidence']={}
 sentences=[m.group().strip() for m in re.finditer(r'[^.!?]+[.!?]?',s['fullDescription']) if len(m.group().strip())>25]
 for c in concepts:
  matching=[x for x in sentences if any(root.replace('ё','е') in x.lower().replace('ё','е') for root in c['sourceRoots'])]
  if matching:
   s['intentEvidence'][c['id']]=matching[0];s['subcategories'].append(c['id'])
 s['categories']=list(dict.fromkeys(c['category'] for c in concepts if c['id'] in s['intentEvidence']))
 s['features']=[c['label'] for c in concepts if c['id'] in s['intentEvidence']]
 s['keywords']=s['features'][:]
 # Structural excerpts are literal, preserving unusual meanings and avoiding generated claims.
 s['importantNotes']=[x for x in sentences if re.search(r'важно|не обязательно|исключени|только|можно прямо|можно даже|главное|особенн',x,re.I)][:3]
 s['usageMethods']=[x for x in sentences if re.search(r'рисова|нанос|носить|амулет|талисман.*(использ|примен)',x,re.I)]
 s['applicationPlaces']=[x for x in s['usageMethods'] if re.search(r'рук|теле|машин|кристалл|камн|манипур|уровне|поле',x,re.I)]
 s['limitations']=[x for x in sentences if re.search(r'не надо|не нужно|нельзя|не рекомендуется|не обязательно',x,re.I)]
 # Trim transcript introductions only in the supplementary short field.
 if len(s['shortDescription'])>330:s['shortDescription']=s['shortDescription'][:327]+'…'
 for t in base:
  if t['id']!=s['id']:
   n=len(set(t['subcategories'])&set(s['subcategories']));
   if n>=4:s['relatedSymbols'].append(t['id'])
 s['relatedSymbols']=s['relatedSymbols'][:4]
( P/'data/symbols.json').write_text(json.dumps(base,ensure_ascii=False,separators=(',',':')))
(P/'data/intents.json').write_text(json.dumps(concepts,ensure_ascii=False,indent=2))
